package com.margelo.nitro.pay

import org.json.JSONArray
import org.json.JSONObject

// Builders shared by the tests. PaymentRequest is generated by Nitrogen, so a
// new field in the spec only needs a default here.

internal fun item(
    label: String,
    amount: String,
    type: PaymentItemType = PaymentItemType.FINAL,
    kind: PaymentItemKind? = null
) = PaymentItem(label = label, amount = PaymentAmount.create(amount), type = type, kind = kind)

internal fun item(label: String, amount: Double, type: PaymentItemType = PaymentItemType.FINAL) =
    PaymentItem(label = label, amount = PaymentAmount.create(amount), type = type, kind = null)

internal fun paymentRequest(
    items: Array<PaymentItem> = emptyArray(),
    currencyCode: String = "USD",
    merchantName: String? = null,
    totalLabel: String? = null,
    environment: GooglePayEnvironment? = null,
    googlePayMerchantId: String? = null,
    googlePayGateway: String? = null,
    googlePayGatewayMerchantId: String? = null,
    billingContactRequired: Boolean? = null,
    shippingContactRequired: Boolean? = null,
    emailRequired: Boolean? = null,
    phoneNumberRequired: Boolean? = null,
    shippingMethods: Array<ShippingMethod>? = null,
    supportedNetworks: Array<String> = arrayOf("visa"),
    googlePayAllowedAuthMethods: Array<String>? = null,
    merchantCapabilities: Array<String> = arrayOf("3DS"),
    recurring: RecurringPaymentRequest? = null,
    deferred: DeferredPaymentRequest? = null,
    automaticReload: AutomaticReloadPaymentRequest? = null
) = PaymentRequest(
    applePayMerchantIdentifier = null,
    merchantName = merchantName,
    totalLabel = totalLabel,
    countryCode = "US",
    currencyCode = currencyCode,
    paymentItems = items,
    merchantCapabilities = merchantCapabilities,
    supportedNetworks = supportedNetworks,
    shippingType = null,
    shippingMethods = shippingMethods,
    billingContactRequired = billingContactRequired,
    shippingContactRequired = shippingContactRequired,
    emailRequired = emailRequired,
    phoneNumberRequired = phoneNumberRequired,
    recurring = recurring,
    deferred = deferred,
    automaticReload = automaticReload,
    applePayMultiTokenContexts = null,
    googlePayMerchantId = googlePayMerchantId,
    googlePayEnvironment = environment,
    googlePayGateway = googlePayGateway,
    googlePayGatewayMerchantId = googlePayGatewayMerchantId,
    googlePayAllowedAuthMethods = googlePayAllowedAuthMethods
)

internal fun JSONArray.objects(): List<JSONObject> = (0 until length()).map { getJSONObject(it) }

internal fun JSONArray.strings(): List<String> = (0 until length()).map { getString(it) }
